-- Import the non-domestic EPC CSV into SQL Server, then check it with check_loaded_digest.sql.
-- Generated by python -m epc_nd_ingest.sql_check from the output schema and the export contract.
--
-- Decompress the file first and edit the path below. Run it against a database of your own:
-- it drops and recreates the table it names and a staging table beside it.
--
-- Verify the file hash against results/manifest.json before importing. After importing, run
-- check_loaded_digest.sql with that manifest's row count and digest total.

SET NOCOUNT ON;
SET XACT_ABORT ON;

-- --------------------------------------------------------------------------------------------
-- epc_nondomestic: stage as text, then restore the declared types. BULK INSERT reads an empty cell as
-- NULL. A published column is NOT NULL and gets the empty string back (ISNULL); a nullable
-- derived column stays NULL (NULLIF). A required typed column that does not convert stops the
-- insert on its NOT NULL constraint.
-- --------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS staging_epc_nondomestic;
CREATE TABLE staging_epc_nondomestic (
    [epc_release] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [source_row] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [HISTORIC] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [BUILDING_REFERENCE_NUMBER] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [OSG_REFERENCE_NUMBER] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [ADDRESS1] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [ADDRESS2] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [POST_TOWN] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [POSTCODE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [INSPECTION_DATE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [LODGEMENT_DATE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [PROPERTY_TYPE_SHORT] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [PROPERTY_TYPE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [FLOOR_AREA] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [CURRENT_ENERGY_PERFORMANCE_RATING] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [CURRENT_ENERGY_PERFORMANCE_BAND] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [POTENTIAL_ENERGY_PERFORMANCE_RATING] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [POTENTIAL_ENERGY_PERFORMANCE_BAND] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [NEW_BUILD_ENERGY_PERFORMANCE_RATING] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [NEW_BUILD_ENERGY_PERFORMANCE_BAND] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [MEETS_2002_STANDARD] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [ASSET_RATING] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [ASSET_RATING_BAND] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [BUILDING_EMISSIONS] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [RENEWABLE_SOURCES] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [ELECTRICITY_SOURCE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [MAIN_HEATING_FUEL] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [BUILDING_ENVIRONMENT] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [PRIMARY_ENERGY_VALUE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [APPROXIMATE_ENERGY_USE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [IMPROVEMENT_RECOMMENDATIONS] varchar(max) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [LOCAL_AUTHORITY] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [DATA_ZONE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [CONSTITUENCY] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [CONSTITUENCY_LABEL] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [TRANSACTION_TYPE] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [TARGET_EMISSIONS] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [DATA_ZONE_2011] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [CREATED_AT] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [REPORT_REFERENCE_NUMBER] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [rrn] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [uprn_sepcr] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [uprn_osg] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [pc_norm] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [datazone_2001] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [datazone_2001_status] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [datazone_2011] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [datazone_2011_status] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [inspection_date_parsed] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [lodgement_date_parsed] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [created_at_parsed] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [historic_flag] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [floor_area_int] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [current_energy_performance_rating_int] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [potential_energy_performance_rating_num] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [building_emissions_num] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL,
    [primary_energy_value_int] varchar(8000) COLLATE Latin1_General_100_BIN2_UTF8 NULL
);

-- EDIT the path. FORMAT = 'CSV' honours RFC 4180 quoting.
-- ROWTERMINATOR is LF, as the contract specifies. CODEPAGE = '65001' makes BULK INSERT read
-- the file as UTF-8: without it the bytes are read in the server's OEM code page whatever
-- the staging collation says, and every cell with a non-ASCII character arrives changed
-- (found in uprn-epc's container probe of 30 October 2026). SQL Server on Linux does not
-- support CODEPAGE: there, convert the file to UTF-16LE with a byte order mark and replace
-- CODEPAGE = '65001' with DATAFILETYPE = 'widechar' and ROWTERMINATOR = '\n', as
-- loader/sqlserver_probe.sh does.
BULK INSERT staging_epc_nondomestic
FROM '/path/to/epc_nondomestic.csv'
WITH (FORMAT = 'CSV', FIELDQUOTE = '"', FIELDTERMINATOR = ',', ROWTERMINATOR = '0x0a',
      CODEPAGE = '65001', FIRSTROW = 2, TABLOCK);

DROP TABLE IF EXISTS epc_nondomestic;
CREATE TABLE epc_nondomestic (
    [epc_release] nvarchar(8) NOT NULL,
    [source_row] int NOT NULL,
    [HISTORIC] nvarchar(8) NOT NULL,
    [BUILDING_REFERENCE_NUMBER] nvarchar(32) NOT NULL,
    [OSG_REFERENCE_NUMBER] nvarchar(32) NOT NULL,
    [ADDRESS1] nvarchar(100) NOT NULL,
    [ADDRESS2] nvarchar(100) NOT NULL,
    [POST_TOWN] nvarchar(100) NOT NULL,
    [POSTCODE] nvarchar(32) NOT NULL,
    [INSPECTION_DATE] nvarchar(32) NOT NULL,
    [LODGEMENT_DATE] nvarchar(32) NOT NULL,
    [PROPERTY_TYPE_SHORT] nvarchar(32) NOT NULL,
    [PROPERTY_TYPE] nvarchar(100) NOT NULL,
    [FLOOR_AREA] nvarchar(8) NOT NULL,
    [CURRENT_ENERGY_PERFORMANCE_RATING] nvarchar(8) NOT NULL,
    [CURRENT_ENERGY_PERFORMANCE_BAND] nvarchar(32) NOT NULL,
    [POTENTIAL_ENERGY_PERFORMANCE_RATING] nvarchar(32) NOT NULL,
    [POTENTIAL_ENERGY_PERFORMANCE_BAND] nvarchar(32) NOT NULL,
    [NEW_BUILD_ENERGY_PERFORMANCE_RATING] nvarchar(8) NOT NULL,
    [NEW_BUILD_ENERGY_PERFORMANCE_BAND] nvarchar(8) NOT NULL,
    [MEETS_2002_STANDARD] nvarchar(8) NOT NULL,
    [ASSET_RATING] nvarchar(32) NOT NULL,
    [ASSET_RATING_BAND] nvarchar(32) NOT NULL,
    [BUILDING_EMISSIONS] nvarchar(32) NOT NULL,
    [RENEWABLE_SOURCES] nvarchar(32) NOT NULL,
    [ELECTRICITY_SOURCE] nvarchar(32) NOT NULL,
    [MAIN_HEATING_FUEL] nvarchar(100) NOT NULL,
    [BUILDING_ENVIRONMENT] nvarchar(100) NOT NULL,
    [PRIMARY_ENERGY_VALUE] nvarchar(8) NOT NULL,
    [APPROXIMATE_ENERGY_USE] nvarchar(8) NOT NULL,
    [IMPROVEMENT_RECOMMENDATIONS] nvarchar(max) NOT NULL,
    [LOCAL_AUTHORITY] nvarchar(8) NOT NULL,
    [DATA_ZONE] nvarchar(100) NOT NULL,
    [CONSTITUENCY] nvarchar(8) NOT NULL,
    [CONSTITUENCY_LABEL] nvarchar(100) NOT NULL,
    [TRANSACTION_TYPE] nvarchar(100) NOT NULL,
    [TARGET_EMISSIONS] nvarchar(8) NOT NULL,
    [DATA_ZONE_2011] nvarchar(100) NOT NULL,
    [CREATED_AT] nvarchar(32) NOT NULL,
    [REPORT_REFERENCE_NUMBER] nvarchar(32) NOT NULL,
    [rrn] nvarchar(24),
    [uprn_sepcr] bigint NOT NULL,
    [uprn_osg] bigint,
    [pc_norm] nvarchar(32),
    [datazone_2001] nvarchar(9),
    [datazone_2001_status] nvarchar(16) NOT NULL,
    [datazone_2011] nvarchar(9),
    [datazone_2011_status] nvarchar(16) NOT NULL,
    [inspection_date_parsed] date NOT NULL,
    [lodgement_date_parsed] date NOT NULL,
    [created_at_parsed] datetime2(0) NOT NULL,
    [historic_flag] bit NOT NULL,
    [floor_area_int] int NOT NULL,
    [current_energy_performance_rating_int] int NOT NULL,
    [potential_energy_performance_rating_num] decimal(19,4),
    [building_emissions_num] decimal(19,4) NOT NULL,
    [primary_energy_value_int] int NOT NULL,
    CONSTRAINT PK_epc_nondomestic PRIMARY KEY ([epc_release], [source_row])
);

INSERT INTO epc_nondomestic (
    [epc_release],
    [source_row],
    [HISTORIC],
    [BUILDING_REFERENCE_NUMBER],
    [OSG_REFERENCE_NUMBER],
    [ADDRESS1],
    [ADDRESS2],
    [POST_TOWN],
    [POSTCODE],
    [INSPECTION_DATE],
    [LODGEMENT_DATE],
    [PROPERTY_TYPE_SHORT],
    [PROPERTY_TYPE],
    [FLOOR_AREA],
    [CURRENT_ENERGY_PERFORMANCE_RATING],
    [CURRENT_ENERGY_PERFORMANCE_BAND],
    [POTENTIAL_ENERGY_PERFORMANCE_RATING],
    [POTENTIAL_ENERGY_PERFORMANCE_BAND],
    [NEW_BUILD_ENERGY_PERFORMANCE_RATING],
    [NEW_BUILD_ENERGY_PERFORMANCE_BAND],
    [MEETS_2002_STANDARD],
    [ASSET_RATING],
    [ASSET_RATING_BAND],
    [BUILDING_EMISSIONS],
    [RENEWABLE_SOURCES],
    [ELECTRICITY_SOURCE],
    [MAIN_HEATING_FUEL],
    [BUILDING_ENVIRONMENT],
    [PRIMARY_ENERGY_VALUE],
    [APPROXIMATE_ENERGY_USE],
    [IMPROVEMENT_RECOMMENDATIONS],
    [LOCAL_AUTHORITY],
    [DATA_ZONE],
    [CONSTITUENCY],
    [CONSTITUENCY_LABEL],
    [TRANSACTION_TYPE],
    [TARGET_EMISSIONS],
    [DATA_ZONE_2011],
    [CREATED_AT],
    [REPORT_REFERENCE_NUMBER],
    [rrn],
    [uprn_sepcr],
    [uprn_osg],
    [pc_norm],
    [datazone_2001],
    [datazone_2001_status],
    [datazone_2011],
    [datazone_2011_status],
    [inspection_date_parsed],
    [lodgement_date_parsed],
    [created_at_parsed],
    [historic_flag],
    [floor_area_int],
    [current_energy_performance_rating_int],
    [potential_energy_performance_rating_num],
    [building_emissions_num],
    [primary_energy_value_int]
)
SELECT
    ISNULL([epc_release], N''),
    CONVERT(int, NULLIF([source_row], '')),
    ISNULL([HISTORIC], N''),
    ISNULL([BUILDING_REFERENCE_NUMBER], N''),
    ISNULL([OSG_REFERENCE_NUMBER], N''),
    ISNULL([ADDRESS1], N''),
    ISNULL([ADDRESS2], N''),
    ISNULL([POST_TOWN], N''),
    ISNULL([POSTCODE], N''),
    ISNULL([INSPECTION_DATE], N''),
    ISNULL([LODGEMENT_DATE], N''),
    ISNULL([PROPERTY_TYPE_SHORT], N''),
    ISNULL([PROPERTY_TYPE], N''),
    ISNULL([FLOOR_AREA], N''),
    ISNULL([CURRENT_ENERGY_PERFORMANCE_RATING], N''),
    ISNULL([CURRENT_ENERGY_PERFORMANCE_BAND], N''),
    ISNULL([POTENTIAL_ENERGY_PERFORMANCE_RATING], N''),
    ISNULL([POTENTIAL_ENERGY_PERFORMANCE_BAND], N''),
    ISNULL([NEW_BUILD_ENERGY_PERFORMANCE_RATING], N''),
    ISNULL([NEW_BUILD_ENERGY_PERFORMANCE_BAND], N''),
    ISNULL([MEETS_2002_STANDARD], N''),
    ISNULL([ASSET_RATING], N''),
    ISNULL([ASSET_RATING_BAND], N''),
    ISNULL([BUILDING_EMISSIONS], N''),
    ISNULL([RENEWABLE_SOURCES], N''),
    ISNULL([ELECTRICITY_SOURCE], N''),
    ISNULL([MAIN_HEATING_FUEL], N''),
    ISNULL([BUILDING_ENVIRONMENT], N''),
    ISNULL([PRIMARY_ENERGY_VALUE], N''),
    ISNULL([APPROXIMATE_ENERGY_USE], N''),
    ISNULL([IMPROVEMENT_RECOMMENDATIONS], N''),
    ISNULL([LOCAL_AUTHORITY], N''),
    ISNULL([DATA_ZONE], N''),
    ISNULL([CONSTITUENCY], N''),
    ISNULL([CONSTITUENCY_LABEL], N''),
    ISNULL([TRANSACTION_TYPE], N''),
    ISNULL([TARGET_EMISSIONS], N''),
    ISNULL([DATA_ZONE_2011], N''),
    ISNULL([CREATED_AT], N''),
    ISNULL([REPORT_REFERENCE_NUMBER], N''),
    NULLIF([rrn], N''),
    CONVERT(bigint, NULLIF([uprn_sepcr], '')),
    CONVERT(bigint, NULLIF([uprn_osg], '')),
    NULLIF([pc_norm], N''),
    NULLIF([datazone_2001], N''),
    ISNULL([datazone_2001_status], N''),
    NULLIF([datazone_2011], N''),
    ISNULL([datazone_2011_status], N''),
    CONVERT(date, NULLIF([inspection_date_parsed], ''), 23),
    CONVERT(date, NULLIF([lodgement_date_parsed], ''), 23),
    CONVERT(datetime2(0), NULLIF([created_at_parsed], ''), 120),
    CONVERT(bit, NULLIF([historic_flag], '')),
    CONVERT(int, NULLIF([floor_area_int], '')),
    CONVERT(int, NULLIF([current_energy_performance_rating_int], '')),
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(19,4), NULLIF([potential_energy_performance_rating_num], ''))) = [potential_energy_performance_rating_num] THEN CONVERT(decimal(19,4), [potential_energy_performance_rating_num]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(19,4), NULLIF([building_emissions_num], ''))) = [building_emissions_num] THEN CONVERT(decimal(19,4), [building_emissions_num]) END,
    CONVERT(int, NULLIF([primary_energy_value_int], ''))
FROM staging_epc_nondomestic;

DROP TABLE IF EXISTS staging_epc_nondomestic;

-- The join routes.
CREATE INDEX IX_epc_nondomestic_uprn_osg ON epc_nondomestic ([uprn_osg], [inspection_date_parsed]) INCLUDE ([historic_flag]);
CREATE INDEX IX_epc_nondomestic_pc_norm ON epc_nondomestic ([pc_norm]) INCLUDE ([uprn_sepcr]);
CREATE INDEX IX_epc_nondomestic_uprn_sepcr ON epc_nondomestic ([uprn_sepcr], [inspection_date_parsed]) INCLUDE ([historic_flag], [pc_norm]);
